/**
 * 🌌 MESURV Geomatics Core: Emlid Studio & RTKLIB .pos Solution Parser
 * Ingests post-processed kinematic/static GNSS solution files (.pos) generated by
 * Emlid Studio (ES 1.x / RTKLIB), extracts Phase Fixed/Float solutions, Ambiguity Ratio,
 * Base-Rover coordinates, standard deviations, and synthesizes 3D Baseline Solutions
 * ready for Least Squares Network Adjustment.
 */

import { type BaselineSolution, type BaselineVectorENU, type AmbiguityStatus } from './gnss-baseline';
import { forwardWgs84ToUtm } from '../core/projections';

export interface EmlidPosRecord {
  gpst: string;
  lat: number;
  lng: number;
  height: number;
  q: number; // 1: Fix, 2: Float, 3: SBAS, 4: DGPS, 5: Single, 6: PPP
  qualityLabel: AmbiguityStatus;
  ns: number; // number of satellites
  sdn: number; // meters
  sde: number; // meters
  sdu: number; // meters
  sdne: number;
  sdeu: number;
  sdun: number;
  ageSec: number;
  ratio: number;
}

export interface EmlidPosParseResult {
  program: string;
  roverFile: string;
  baseFile: string;
  navFile: string;
  obsStart: string;
  obsEnd: string;
  refPosition: {
    lat: number;
    lng: number;
    height: number;
    utmE: number;
    utmN: number;
    zone: number;
  } | null;
  computedPosition: {
    lat: number;
    lng: number;
    height: number;
    utmE: number;
    utmN: number;
    zone: number;
  };
  vectorENU: BaselineVectorENU;
  overallStatus: AmbiguityStatus;
  averageRatio: number;
  bestRatio: number;
  fixedEpochsCount: number;
  totalEpochsCount: number;
  averageStdDevMm: {
    dN: number;
    dE: number;
    dU: number;
  };
  records: EmlidPosRecord[];
  asBaselineSolution(baseName?: string, roverName?: string): BaselineSolution;
}

/**
 * Checks whether the given text is a valid Emlid Studio or RTKLIB .pos file.
 */
export function isEmlidPosText(text: string): boolean {
  return (
    text.includes('% program   : ES') ||
    text.includes('% program   : RTKLIB') ||
    (text.includes('latitude(deg)') && text.includes('longitude(deg)') && text.includes('sdn(m)'))
  );
}

/**
 * Parses an Emlid Studio / RTKLIB .pos text output into a structured geodetic solution.
 */
export function parseEmlidPosText(text: string, defaultFileName: string = 'solution.pos'): EmlidPosParseResult {
  const lines = text.split(/\r?\n/);

  let program = 'Emlid Studio / RTKLIB';
  let roverFile = '';
  let baseFile = '';
  let navFile = '';
  let obsStart = '';
  let obsEnd = '';
  let refPos: { lat: number; lng: number; height: number } | null = null;

  const records: EmlidPosRecord[] = [];

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim();
    if (!line) continue;

    if (line.startsWith('%')) {
      const lower = line.toLowerCase();
      if (lower.includes('% program')) {
        program = line.substring(line.indexOf(':') + 1).trim();
      } else if (lower.includes('% inp file')) {
        const path = line.substring(line.indexOf(':') + 1).trim();
        const baseName = path.split(/[\\/]/).pop() || '';
        if (/\.2\d[oO]$|\.obs$/i.test(baseName)) {
          if (!roverFile) roverFile = baseName;
          else if (!baseFile) baseFile = baseName;
        } else if (/\.2\d[nNpPcCgGlL]$|\.nav$/i.test(baseName)) {
          navFile = baseName;
        }
      } else if (lower.includes('% obs start')) {
        obsStart = line.substring(line.indexOf(':') + 1).trim();
      } else if (lower.includes('% obs end')) {
        obsEnd = line.substring(line.indexOf(':') + 1).trim();
      } else if (lower.includes('% ref pos')) {
        const parts = line.substring(line.indexOf(':') + 1).trim().split(/\s+/).map(Number);
        if (parts.length >= 3 && !parts.some(isNaN)) {
          refPos = { lat: parts[0], lng: parts[1], height: parts[2] };
        }
      }
      continue;
    }

    // Data row: GPST(date time) lat lon height Q ns sdn sde sdu sdne sdeu sdun age ratio
    const tokens = line.split(/\s+/);
    if (tokens.length >= 14) {
      const gpst = `${tokens[0]} ${tokens[1]}`;
      const lat = parseFloat(tokens[2]);
      const lng = parseFloat(tokens[3]);
      const height = parseFloat(tokens[4]);
      const q = parseInt(tokens[5], 10);
      const ns = parseInt(tokens[6], 10);
      const sdn = parseFloat(tokens[7]);
      const sde = parseFloat(tokens[8]);
      const sdu = parseFloat(tokens[9]);
      const sdne = parseFloat(tokens[10]);
      const sdeu = parseFloat(tokens[11]);
      const sdun = parseFloat(tokens[12]);
      const ageSec = parseFloat(tokens[13]);
      const ratio = tokens.length > 14 ? parseFloat(tokens[14]) : 0;

      if (!isNaN(lat) && !isNaN(lng) && !isNaN(height)) {
        records.push({
          gpst,
          lat,
          lng,
          height,
          q,
          qualityLabel: q === 1 ? 'FIXED' : 'FLOAT',
          ns,
          sdn,
          sde,
          sdu,
          sdne,
          sdeu,
          sdun,
          ageSec,
          ratio: isNaN(ratio) ? 0 : ratio
        });
      }
    }
  }

  if (records.length === 0) {
    throw new Error('ไม่พบข้อมูลผลลัพธ์พิกัดในไฟล์ .pos (กรุณาตรวจสอบว่ามีข้อมูล Solution แถวพิกัดหรือไม่)');
  }

  // Compute final representative solution:
  // Prefer the last Fixed record, or average of Fixed records, or last record if all float
  const fixedRecords = records.filter(r => r.q === 1);
  const targetRecords = fixedRecords.length > 0 ? fixedRecords : records;

  let sumLat = 0, sumLng = 0, sumH = 0;
  let sumSdn = 0, sumSde = 0, sumSdu = 0;
  let sumRatio = 0, maxRatio = 0;

  for (const r of targetRecords) {
    sumLat += r.lat;
    sumLng += r.lng;
    sumH += r.height;
    sumSdn += r.sdn;
    sumSde += r.sde;
    sumSdu += r.sdu;
    sumRatio += r.ratio;
    if (r.ratio > maxRatio) maxRatio = r.ratio;
  }

  const count = targetRecords.length;
  const avgLat = sumLat / count;
  const avgLng = sumLng / count;
  const avgH = sumH / count;

  const roverUtm = forwardWgs84ToUtm(avgLat, avgLng);

  let refUtm = refPos ? forwardWgs84ToUtm(refPos.lat, refPos.lng) : null;

  // Calculate baseline vector if reference position is available
  let dE = 0, dN = 0, dU = 0;
  let dist2D = 0, dist3D = 0, azDeg = 0;

  if (refPos && refUtm) {
    dE = roverUtm.easting - refUtm.easting;
    dN = roverUtm.northing - refUtm.northing;
    dU = avgH - refPos.height;
    dist2D = Math.hypot(dE, dN);
    dist3D = Math.hypot(dE, dN, dU);
    let azRad = Math.atan2(dE, dN);
    azDeg = (azRad * 180.0) / Math.PI;
    if (azDeg < 0) azDeg += 360.0;
  }

  const vectorENU: BaselineVectorENU = {
    dE,
    dN,
    dU,
    distance2D: dist2D,
    distance3D: dist3D,
    azimuthDeg: Math.round(azDeg * 1000) / 1000
  };

  const overallStatus: AmbiguityStatus = fixedRecords.length / records.length >= 0.5 ? 'FIXED' : 'FLOAT';

  const avgStdDevMm = {
    dN: Math.round((sumSdn / count) * 10000) / 10,
    dE: Math.round((sumSde / count) * 10000) / 10,
    dU: Math.round((sumSdu / count) * 10000) / 10
  };

  const result: EmlidPosParseResult = {
    program,
    roverFile,
    baseFile,
    navFile,
    obsStart,
    obsEnd,
    refPosition: refPos && refUtm ? {
      lat: refPos.lat,
      lng: refPos.lng,
      height: refPos.height,
      utmE: refUtm.easting,
      utmN: refUtm.northing,
      zone: refUtm.zone
    } : null,
    computedPosition: {
      lat: avgLat,
      lng: avgLng,
      height: avgH,
      utmE: roverUtm.easting,
      utmN: roverUtm.northing,
      zone: roverUtm.zone
    },
    vectorENU,
    overallStatus,
    averageRatio: Math.round((sumRatio / count) * 10) / 10,
    bestRatio: Math.round(maxRatio * 10) / 10,
    fixedEpochsCount: fixedRecords.length,
    totalEpochsCount: records.length,
    averageStdDevMm: avgStdDevMm,
    records,
    asBaselineSolution(baseName = 'BASE', roverName = 'ROVER'): BaselineSolution {
      const varE = Math.pow(Math.max(avgStdDevMm.dE / 1000, 0.001), 2);
      const varN = Math.pow(Math.max(avgStdDevMm.dN / 1000, 0.001), 2);
      const varU = Math.pow(Math.max(avgStdDevMm.dU / 1000, 0.002), 2);

      return {
        id: `${baseName}_to_${roverName}`,
        baseStation: baseName,
        roverStation: roverName,
        status: overallStatus,
        ratioTest: Math.max(maxRatio, 3.0),
        commonSatellites: Math.round(records.reduce((acc, r) => acc + r.ns, 0) / records.length) || 12,
        elevationMaskDeg: 15,
        durationMinutes: Math.max(15, Math.round(records.length / 60)),
        vectorECEF: {
          dx: vectorENU.dE, // simplified local mapping for display
          dy: vectorENU.dN,
          dz: vectorENU.dU
        },
        vectorENU,
        stdDevMm: {
          dx: avgStdDevMm.dE,
          dy: avgStdDevMm.dN,
          dz: avgStdDevMm.dU,
          dE: avgStdDevMm.dE,
          dN: avgStdDevMm.dN,
          dU: avgStdDevMm.dU
        },
        covarianceMatrixENU: [
          [varE, 0, 0],
          [0, varN, 0],
          [0, 0, varU]
        ]
      };
    }
  };

  return result;
}
